import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.ZNXClGez.js";const p=JSON.parse('{"title":"Trust Anchors (Trusted CAs)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/user/trust-anchors.md","filePath":"guide/user/trust-anchors.md"}'),r={name:"guide/user/trust-anchors.md"};function s(o,e,c,l,d,h){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="trust-anchors-trusted-cas" tabindex="-1">Trust Anchors (Trusted CAs) <a class="header-anchor" href="#trust-anchors-trusted-cas" aria-label="Permalink to &quot;Trust Anchors (Trusted CAs)&quot;">​</a></h1><p>A <strong>trust anchor</strong> is a CA certificate that you explicitly choose to trust. It is the point where certificate-chain validation stops: a certificate is trusted only when its chain can be verified back to an enabled trust anchor.</p><p>A trust anchor is therefore both:</p><ul><li>a public X.509 CA certificate; and</li><li>an administrative trust decision for one Authup realm.</li></ul><p>The certificate alone contains no secret. The CA private key remains with the CA and must never be uploaded as a trust anchor.</p><p>Authup consumes enabled anchors when an OAuth client uses <code>authMethod: tls</code>. Adding an anchor alone does not turn clients into TLS clients; configure the client and trusted proxy separately. See <a href="./client-certificates.html">OAuth Client Certificates</a>.</p><h2 id="how-certificate-trust-works" tabindex="-1">How certificate trust works <a class="header-anchor" href="#how-certificate-trust-works" aria-label="Permalink to &quot;How certificate trust works&quot;">​</a></h2><p>A client normally holds a leaf certificate and its private key. A CA signs the leaf certificate, possibly through one or more intermediate CAs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client certificate -&gt; intermediate CA -&gt; trusted CA</span></span>
<span class="line"><span>                                           ^</span></span>
<span class="line"><span>                                           |</span></span>
<span class="line"><span>                                    Authup trust anchor</span></span></code></pre></div><p>The client proves possession of its private key during the TLS handshake. Certificate-chain validation then establishes whether the presented public certificate was issued by a CA that the realm trusts. Client identity checks, such as matching a URI SAN to an OAuth client, are a separate step; a valid chain alone does not identify which Authup client is connecting.</p><p>A trust anchor does not have to be a self-signed root CA. Trusting a dedicated intermediate CA can be safer because it limits trust to certificates issued under that intermediate.</p><h2 id="intended-use-cases" tabindex="-1">Intended use cases <a class="header-anchor" href="#intended-use-cases" aria-label="Permalink to &quot;Intended use cases&quot;">​</a></h2><p>Trust anchors are intended for certificate-based machine authentication, in particular:</p><ul><li><strong>OAuth 2.0 mTLS client authentication:</strong> authenticate a client at the token endpoint using a certificate issued by a trusted organizational or partner CA.</li><li><strong>Externally issued client certificates:</strong> use certificates from an existing internal PKI without importing CA private keys into Authup.</li><li><strong>Partner-specific trust:</strong> trust different partner or workload CAs in different realms.</li><li><strong>CA rotation:</strong> enable old and new CA certificates during a migration, then disable the old anchor after all client certificates have been replaced.</li><li><strong>Certificate-bound access tokens:</strong> prevent a copied access or refresh token from being used without the corresponding client certificate and private key. Token binding is independently configurable and does not itself require a trust anchor.</li></ul><p>Use a dedicated client-authentication CA or intermediate with a narrow issuance policy. Avoid adding a broad public Web PKI root merely because it is already widely trusted: that greatly expands the population of certificates that can reach the later identity-validation step.</p><h2 id="what-a-trust-anchor-is-not" tabindex="-1">What a trust anchor is not <a class="header-anchor" href="#what-a-trust-anchor-is-not" aria-label="Permalink to &quot;What a trust anchor is not&quot;">​</a></h2><p>Several certificate-related objects serve different purposes:</p><table tabindex="0"><thead><tr><th>Object</th><th>Purpose</th><th>Private key in Authup?</th></tr></thead><tbody><tr><td><strong>Trust anchor</strong></td><td>Validates client-certificate chains for one realm</td><td>No</td></tr><tr><td><strong>Client certificate</strong></td><td>Identifies a client and proves possession during mTLS</td><td>No; the client keeps it</td></tr><tr><td><strong>Authup signing key</strong></td><td>Signs Authup tokens; may publish an attached certificate through JWKS</td><td>Yes, for signing</td></tr><tr><td><strong>NGINX server certificate</strong></td><td>Identifies the HTTPS endpoint to browsers and clients</td><td>No; NGINX keeps it</td></tr></tbody></table><p>In particular, do not add the following as trust anchors:</p><ul><li>the HTTPS server certificate used by NGINX;</li><li>a normal client leaf certificate;</li><li>an Authup token-signing certificate or public key; or</li><li>a CA certificate whose operator and issuance policy you do not intentionally trust for client authentication.</li></ul><p>Self-signed client-certificate <strong>authentication</strong> is a different mode and is not supported by <code>authMethod: tls</code>; authentication must chain to a realm anchor. A self-signed leaf can still be used for binding-only proof of possession when <code>tokenBindingMethod: tls</code>.</p><h2 id="realm-scope-and-lifecycle" tabindex="-1">Realm scope and lifecycle <a class="header-anchor" href="#realm-scope-and-lifecycle" aria-label="Permalink to &quot;Realm scope and lifecycle&quot;">​</a></h2><p>Trust anchors are realm-scoped. An anchor configured in one realm does not grant trust in another realm.</p><p>Each entry has:</p><ul><li><strong>Name:</strong> a stable administrative identifier, unique inside the realm.</li><li><strong>Certificate:</strong> a PEM-encoded CA certificate or CA chain. The first certificate must be a CA certificate (<code>CA:TRUE</code>).</li><li><strong>Enabled:</strong> whether future certificate consumers may use the anchor.</li></ul><p>The certificate is immutable. To replace it, create the replacement anchor and then disable or delete the old entry. This makes CA rotation explicit and allows an overlap period.</p><p>To manage anchors in the admin UI:</p><ol><li>Select the target realm.</li><li>Open <strong>Trusted CAs</strong> in the sidebar. The API and domain model call these trust anchors.</li><li>Add the PEM-encoded CA certificate and choose a descriptive name.</li><li>Leave the anchor enabled only while that CA should be trusted.</li></ol><p>Trust-anchor administration uses the same <code>KEY_*</code> permissions as key management. Realm administrators can manage anchors only in their own realm.</p><h2 id="nginx-and-private-backend-networks" tabindex="-1">NGINX and private backend networks <a class="header-anchor" href="#nginx-and-private-backend-networks" aria-label="Permalink to &quot;NGINX and private backend networks&quot;">​</a></h2><p>In the intended production topology, NGINX or another load balancer terminates HTTPS/mTLS. Authup remains reachable only through the private container or Kubernetes network:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client -- HTTPS/mTLS --&gt; NGINX -- private HTTP --&gt; Authup</span></span>
<span class="line"><span>                         |                         |</span></span>
<span class="line"><span>                         | forwards certificate   | validates against</span></span>
<span class="line"><span>                         | evidence                | realm trust anchors</span></span></code></pre></div><p>The responsibilities are separate:</p><ul><li>NGINX owns the TLS connection and proves that certificate evidence came from the handshake.</li><li>Authup owns the realm-specific CA-chain and OAuth client-identity checks.</li><li>The Authup listener must not be publicly reachable, because public callers must not be able to inject forwarded-certificate headers directly.</li><li>The proxy must remove or overwrite certificate headers received from the public request, including requests where no client certificate was negotiated.</li></ul><p>Trust anchors do not configure NGINX automatically and are not a replacement for the HTTPS server certificate installed at NGINX. See the <a href="./../deployment/nginx.html">NGINX</a> or <a href="./../deployment/traefik.html">Traefik</a> forwarding configuration.</p><h2 id="when-you-do-not-need-trust-anchors" tabindex="-1">When you do not need trust anchors <a class="header-anchor" href="#when-you-do-not-need-trust-anchors" aria-label="Permalink to &quot;When you do not need trust anchors&quot;">​</a></h2><p>You do not need a trust anchor for ordinary OAuth clients using <code>none</code> or a shared secret, nor for binding-only certificates. You also do not need one merely to serve Authup over HTTPS or to publish token-signing certificates through JWKS.</p>`,37)])])}const f=t(r,[["render",s]]);export{p as __pageData,f as default};
